    public class FirResampler
    {
        // This code was generated by Google Gemini and modified by Paul Jensen on 9/28/2026

        private readonly int _l; // Interpolation factor
        private readonly int _m; // Decimation factor
        private readonly float[] _taps; // FIR filter coefficients

        //// Internal state buffers for streaming audio
        //private readonly float[] _delayLine;
        //private readonly int _delayLineHead = 0;

        /// <summary>
        /// Creates a new FIR filter resampler
        /// </summary>
        /// <param name="inputRate">The input sample rate.</param>
        /// <param name="outputRate">The output sample rate.</param>
        /// <param name="filterLength">The length of the filter. Values between 128 (default) and 256 are best.</param>
        public FirResampler(int inputRate, int outputRate, int filterLength = 128)
        {
            // 1. Calculate exact L and M ratios using GCD
            int gcd = GetGcd(inputRate, outputRate);
            _l = outputRate / gcd;
            _m = inputRate / gcd;

            // 2. Design the anti-aliasing low-pass filter
            // The cutoff frequency must be the minimum of the Nyquist frequencies
            double cutoff = Math.Min(1.0 / _l, 1.0 / _m) * 0.5;
            
            _taps = new float[filterLength];
            int center = filterLength / 2;

            for (int n = 0; n < filterLength; n++)
            {
                if (n == center)
                {
                    _taps[n] = (float)(2.0 * cutoff);
                }
                else
                {
                    double angle = 2.0 * Math.PI * cutoff * (n - center);
                    _taps[n] = (float)(Math.Sin(angle) / (Math.PI * (n - center)));
                }

                // Apply Hann Windowing to reduce ripple spectral leakage
                double window = 0.5 * (1.0 - Math.Cos(2.0 * Math.PI * n / (filterLength - 1)));
                _taps[n] *= (float)window;
            }

            // Scale taps to maintain unity gain during interpolation
            for (int i = 0; i < _taps.Length; i++)
            {
                _taps[i] *= _l;
            }

            //_delayLine = new float[filterLength];
        }

        /// <summary>
        /// Gets a resampled output from an array of input samples.
        /// </summary>
        /// <param name="input">The array of input samples.</param>
        /// <returns>Resampled output as an array.</returns>
        public float[] Resample(float[] input)
        {
            // Calculate the precise output size required
            long totalOutputSamples = (long)input.Length * _l / _m;
            float[] output = new float[totalOutputSamples];

            int outIdx = 0;

            // Loop through the virtual upsampled grid
            for (long t = 0; t < (long)input.Length * _l; t += _m)
            {
                if (outIdx >= output.Length) break;

                // Map current virtual index back to input samples
                int inputIdx = (int)(t / _l);
                int subPhase = (int)(t % _l);

                // In a streaming architecture, you would push inputIdx into a buffer.
                // For this direct array processing wrapper:
                output[outIdx++] = ConvolvePolyphase(input, inputIdx, subPhase);
            }

            return output;
        }

        private float ConvolvePolyphase(float[] input, int inputIdx, int subPhase)
        {
            float sum = 0f;

            // Convolve the FIR filter with the input signal
            for (int i = 0; i < _taps.Length; i++)
            {
                // Polyphase time alignment
                int tapIdx = i;
                int virtualTime = tapIdx * _l + subPhase;

                if (virtualTime % _l == 0)
                {
                    int sampleOffset = inputIdx - (virtualTime / _l);
                    if (sampleOffset >= 0 && sampleOffset < input.Length)
                    {
                        sum += input[sampleOffset] * _taps[tapIdx];
                    }
                }
            }

            return sum;
        }

        /// <summary>
        /// Gets the greatest common denominator (GCD) of two numbers.
        /// </summary>
        /// <param name="a">The first number.</param>
        /// <param name="b">The second number.</param>
        /// <returns>The greatest common denominator (GCD) of the two numbers.</returns>
        private int GetGcd(int a, int b)
        {
            while (b != 0)
            {
                int temp = b;
                b = a % b;
                a = temp;
            }
            return a;
        }
    }

